import React from 'react';
import { groupByDate } from '../utils';
import { Chart } from 'react-chartjs-2';
// import { Button } from 'primereact/button';
import ExportCSVButton from './ExportCSVButton';

export default function Summary({ orders, expenses }) {
  const oBy = groupByDate(orders);
  const eBy = groupByDate(expenses);
  const dates = [...new Set([...Object.keys(oBy), ...Object.keys(eBy)])].sort();

  const labels = dates;
  const orderTotals = dates.map(d => (oBy[d] || []).reduce((s, i) => s + i.amount, 0));
  const expenseTotals = dates.map(d => (eBy[d] || []).reduce((s, i) => s + i.amount, 0));

  const chartData = {
    labels,
    datasets: [
      { label: 'Orders', data: orderTotals, borderColor: '#007bff', fill: false },
      { label: 'Expenses', data: expenseTotals, borderColor: '#dc3545', fill: false }
    ]
  };

  const csvData = dates.map(d => ({
    date: d,
    orders: orderTotals[dates.indexOf(d)],
    expenses: expenseTotals[dates.indexOf(d)],
    net: orderTotals[dates.indexOf(d)] - expenseTotals[dates.indexOf(d)]
  }));

  return (
    <div className="p-3 border rounded bg-white">
      <h5>Summary</h5>
      <div className="chart-container mb-3">
        <Chart type="line" data={chartData} />
      </div>
      <ExportCSVButton data={csvData} filename="summary.csv" />
    </div>
  );
}
