import React, { useState, useEffect } from 'react';
import OrderForm from './components/OrderForm';
import ExpenseForm from './components/ExpenseForm';
import OrderList from './components/OrderList';
import ExpenseList from './components/ExpenseList';
import Summary from './components/Summary';
import { InputSwitch } from 'primereact/inputswitch';

export default function App() {
  const [orders, setOrders] = useState(() => JSON.parse(localStorage.getItem('orders') || '[]'));
  const [expenses, setExpenses] = useState(() => JSON.parse(localStorage.getItem('expenses') || '[]'));
  const [tab, setTab] = useState('orders');
  const [dark, setDark] = useState(localStorage.getItem('dark') === 'true');

  useEffect(() => { localStorage.setItem('orders', JSON.stringify(orders)); }, [orders]);
  useEffect(() => { localStorage.setItem('expenses', JSON.stringify(expenses)); }, [expenses]);
  useEffect(() => {
    document.body.classList.toggle('dark', dark);
    localStorage.setItem('dark', dark);
  }, [dark]);

  const addOrder = o => setOrders([o, ...orders]);
  const addExpense = e => setExpenses([e, ...expenses]);

  return (
    <div className="container py-4">
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2>Order Manager</h2>
        <div className="d-flex align-items-center">
          <span className="me-2">Dark Mode</span>
          <InputSwitch checked={dark} onChange={e => setDark(e.value)} />
        </div>
      </div>

      <nav className="nav nav-tabs mb-3">
        <button className={`nav-link ${tab === 'orders' ? 'active' : ''}`} onClick={()=>setTab('orders')}>Orders</button>
        <button className={`nav-link ${tab === 'expenses' ? 'active' : ''}`} onClick={()=>setTab('expenses')}>Expenses</button>
        <button className={`nav-link ${tab === 'summary' ? 'active' : ''}`} onClick={()=>setTab('summary')}>Summary</button>
      </nav>

      {tab === 'orders' && <>
        <OrderForm add={addOrder} />
        <OrderList data={orders} field="amount" />
      </>}

      {tab === 'expenses' && <>
        <ExpenseForm add={addExpense} />
        <ExpenseList data={expenses} field="amount" />
      </>}

      {tab === 'summary' && <Summary orders={orders} expenses={expenses} />}
    </div>
  );
}
