import React from 'react';
import { DataTable } from 'primereact/datatable';
import { Column } from 'primereact/column';

export default function OrderList({ data }) {
  return (
    <div className="card p-3 mb-3">
      <h5 className="mb-3">Orders List</h5>
      <DataTable value={data} paginator rows={5} sortMode="multiple" responsiveLayout="stack">
        <Column field="date" header="Date" sortable></Column>
        <Column field="description" header="Description" sortable></Column>
        <Column field="amount" header="Amount (₹)" body={amountTemplate} sortable></Column>
      </DataTable>
    </div>
  );
}

function amountTemplate(rowData) {
  return `₹${rowData.amount.toFixed(2)}`;
}
