import React from 'react';
import { ListBox } from 'primereact/listbox';

export default function OrderList({ data, field }) {
  const items = data.map(o => ({
    label: `${o.date}: ${o.description} — ₹${o[field].toFixed(2)}`,
    value: o.id
  }));
  return <ListBox options={items} style={{ width: '100%' }} />;
}
